/**
 * 12-row production method registry.
 * Mechanized verbatim from the #1165 frozen shape (rev11).
 *
 * Every row carries machine-readable metadata:
 *   - method name, direction, grant requirement
 *   - notification flag (only row 10)
 *   - ready status (ALL false — reservation-only lifecycle, D0 = A)
 *   - leaf closure status and which matrix entries cause reservation
 *   - settlement key source
 *
 * A row may be marked `ready` only when its matrix entries all reach
 * CLOSED + generated byte proofs + N/N+1 conformance pass.
 * This module defines nothing new.
 *
 * ## Reserved matrix entry in-flight coordinates
 *
 * M7 — future-write admission half in review at clowder-ai#1185
 *      (exact 05ad80c6, gate PASS, Fable APPROVE current HEAD);
 *      stored-data attestation/migration half outstanding.
 *      Affects rows 6, 8, 9. M7 remains RESERVED.
 */

import type { Capability } from '../generated/contract.generated.js';

// ---------------------------------------------------------------------------
// Direction + Grant types
// ---------------------------------------------------------------------------

/** Message direction on the wire. */
export type MethodDirection = 'plugin-to-host' | 'host-to-plugin';

/** Grant required to invoke a method, or protocol-intrinsic for handshake/lifecycle. */
export type GrantRequirement = Capability | 'protocol-intrinsic';

/** Leaf closure status from the variable-width leaf matrix. */
export type LeafClosureStatus = 'CLOSED' | 'RESERVED';

// ---------------------------------------------------------------------------
// Registry row shape
// ---------------------------------------------------------------------------

/**
 * A single row of the production method registry.
 * ready is typed as `false` — the reservation-only lifecycle means
 * every row is unpublished and unadvertised.
 */
export interface RegistryRow {
  readonly rowNumber: number;
  readonly method: string;
  readonly direction: MethodDirection;
  readonly grant: GrantRequirement;
  readonly isNotification: boolean;
  readonly ready: false;
  readonly leafClosure: LeafClosureStatus;
  readonly reservedEntries: readonly string[];
  readonly settlementKeySource: string;
}

// ---------------------------------------------------------------------------
// Method name enum
// ---------------------------------------------------------------------------

/**
 * The exact 12 production method names, in registry order.
 * No production method exists for fixture setup/observe, grant presets,
 * revocation, permission-matrix inspection, or replay deletion.
 */
export const WIRE_METHOD_NAMES = [
  'broker.hello',
  'broker.ready',
  'messaging.send',
  'messaging.appendElements',
  'messaging.subscribe',
  'messaging.read',
  'messaging.ack',
  'messaging.snapshot',
  'host.messaging.deliver',
  'host.grants.changed',
  'host.lifecycle.ping',
  'host.lifecycle.drain',
] as const;

/** Union of all 12 production method names. */
export type WireMethodName = (typeof WIRE_METHOD_NAMES)[number];

