// ---------------------------------------------------------------------------
// Derived helpers
// ---------------------------------------------------------------------------

/** Plugin-to-host method names. */
export const PLUGIN_TO_HOST_METHODS: readonly WireMethodName[] =
  WIRE_METHOD_NAMES.filter(m => WIRE_METHOD_REGISTRY[m].direction === 'plugin-to-host');

/** Host-to-plugin method names. */
export const HOST_TO_PLUGIN_METHODS: readonly WireMethodName[] =
  WIRE_METHOD_NAMES.filter(m => WIRE_METHOD_REGISTRY[m].direction === 'host-to-plugin');

/** Notification method names (only row 10 in v0). */
export const NOTIFICATION_METHODS: readonly WireMethodName[] =
  WIRE_METHOD_NAMES.filter(m => WIRE_METHOD_REGISTRY[m].isNotification);

/** Method names with CLOSED leaf shapes (frozen). */
export const CLOSED_LEAF_ROWS: readonly WireMethodName[] =
  WIRE_METHOD_NAMES.filter(m => WIRE_METHOD_REGISTRY[m].leafClosure === 'CLOSED');

/** Method names with RESERVED leaf shapes (may change). */
export const RESERVED_LEAF_ROWS: readonly WireMethodName[] =
  WIRE_METHOD_NAMES.filter(m => WIRE_METHOD_REGISTRY[m].leafClosure === 'RESERVED');

/** Total number of production methods. */
export const WIRE_METHOD_COUNT = 12 as const;

// ---------------------------------------------------------------------------
// Lookup helpers
// ---------------------------------------------------------------------------

/**
 * Look up a registry row by method name.
 * Returns undefined for unknown method names.
 */
export function getRegistryRow(method: string): RegistryRow | undefined {
  return (WIRE_METHOD_REGISTRY as Record<string, RegistryRow>)[method];
}

/**
 * Check whether a method name is a valid wire method.
 */
export function isWireMethod(method: string): method is WireMethodName {
  return (WIRE_METHOD_NAMES as readonly string[]).includes(method);
}

/**
 * Get the grant requirement for a method.
 * Returns undefined for unknown method names.
 */
export function getMethodGrant(method: string): GrantRequirement | undefined {
  return getRegistryRow(method)?.grant;
}
